INSERT INTO testimonials (id, business_id, name, photo, text, rating, active, demo, "order") VALUES ('tst_mtcyc1j12ufxs6g', 'biz_demo_beauty', 'Rodrigo A.', '{"id":"img_mtcyc1j12vvakgn","type":"url","url":"https://images.unsplash.com/photo-1576558656222-ba66febe3dec?auto=format&fit=crop&q=80&w=200&h=200","alt":"Rodrigo A.","createdAt":"2026-08-28T12:52:40.765Z"}'::jsonb, 'O corte ficou perfeito e o ambiente é muito agradável. Voltarei sempre.', 5, TRUE, TRUE, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO testimonials (id, business_id, name, photo, text, rating, active, demo, "order") VALUES ('tst_mtcyc1j12wohdy5', 'biz_demo_beauty', 'Marina R.', '{"id":"img_mtcyc1j12xjtsbr","type":"url","url":"https://images.unsplash.com/photo-1607569708758-0270aa4651bd?auto=format&fit=crop&q=80&w=200&h=200","alt":"Marina R.","createdAt":"2026-08-28T12:52:40.765Z"}'::jsonb, 'Minha coloração ficou exatamente como eu queria. Equipe muito atenciosa.', 5, TRUE, TRUE, 2) ON CONFLICT (id) DO NOTHING;
